onClick:
{{
  (() => {
    const selection = appsmith.store.commande_selection || {};
    const selectedIds = Object.keys(selection).filter(id => selection[id] === true);

    if (selectedIds.length === 0) {
      showAlert('Veuillez cocher au moins un article à commander !', 'warning');
      return;
    }

    resetWidget('Input_Ref_Commande_Fournisseur', true);
    resetWidget('DatePicker_Livraison', true);
    showModal('modal_valider_commande_fournis');
  })()
}}

tooltip:
{{
  (() => {
    const selection = appsmith.store.commande_selection || {};
    const lignes = (Table_Achats.tableData || []).filter(r => selection[r.ID_Ligne_Achat] === true);
    if (lignes.length === 0) return "Sélectionnez des pièces avec le bouton + pour commander";

    const qte = lignes.reduce((acc, r) => acc + Number(r.Quantite || 0), 0);
    const total = lignes.reduce((acc, r) => acc + (Number(r.Quantite || 0) * Number(r.Prix_Achat || 0)), 0);

    return `Panier : ${qte} pièce(s) — Total : ${total.toLocaleString('fr-FR', { style: 'currency', currency: 'EUR' })}`;
  })()
}}
